"""Extreme night misses of the market model with Timestral on the shift (notes 21.57): truth substituted input by input, and the shift surprise by where it sat."""
import numpy as np, pandas as pd, warnings; warnings.filterwarnings("ignore")
import market1 as M
SP = M.SP; P = np.load(f"{SP}/out/market1n_post.npz"); th = {k: float(np.median(P[k])) for k in M.PN}; Z = np.load(f"{SP}/out/shift15.npz"); R = pd.read_parquet(f"{SP}/out/market1n_rows.parquet"); R.index = R.index.tz_convert("UTC")
E = np.load(f"{SP}/out/eua_15min.npz")["eua"]; Rh = pd.read_parquet(f"{SP}/out/market_hourly.parquet"); E = np.r_[E, np.full(max(0, len(Rh) * 4 - len(E)), np.nan)]; co2f = pd.Series(np.nanmean(E[: len(Rh) * 4].reshape(-1, 4), 1), index=Rh.index.tz_convert("UTC")).ffill(); Lact = (1.85 * Rh.gas + 0.37 * co2f.values); Lact.index = Rh.index.tz_convert("UTC")
COMP = ["eX", "d_l", "d_c", "d_g", "eS", "eps"]; rows = []
for per in ("winter", "summer", "autumn"):
    I = np.load(f"{SP}/out/inputs_{per}.npz"); a = I["actual"].astype(float)[:, :24]; V = "v2" if per == "autumn" else "mid"; T = np.load(f"{SP}/out/tsshift_{V}_{per}.npz"); G = np.load(f"{SP}/out/gen_{V}_{per}.npz"); tp = np.load(f"{SP}/out/tsm_rl{'v2' if per == 'autumn' else ''}_{per}.npz")["median"].astype(float)[:, :24]; FB = np.load(f"{SP}/out/shiftfc_{V}_{per}.npz"); BW = (np.maximum(FB["q05"], FB["q95"]) - np.minimum(FB["q05"], FB["q95"])).astype(float)[:, :24].mean(1); BLO = np.minimum(FB["q05"], FB["q95"]).astype(float)[:, :24].mean(1); BHI = np.maximum(FB["q05"], FB["q95"]).astype(float)[:, :24].mean(1)   # autumn on the strict weather basis (21.56)
    for j, c in enumerate(I["cutoffs"]):
        d0 = int(I["cuts"][j]); t0 = pd.Timestamp(str(c)).tz_localize("UTC"); cj = float(co2f.asof(t0 - pd.Timedelta(hours=34))); Lj = 1.85 * float(I["gas"][j]) + 0.37 * cj; sl = slice(d0, d0 + 24); Lv, cv = np.full(24, Lj), np.full(24, cj)
        xh = T["xh"][j].astype(float)[:24]; nbh = T["nbh"][j].astype(float)[:24]; uh = T["median"][j].astype(float)[:24]; rlt = Z["rl"][sl]; x1 = xh + (rlt - G["rl_pes"][j].astype(float)[:24]); x2 = rlt - Z["other"][sl]; nbt = Z["nbterm"][sl]; ut = x2 - Z["Sp"][sl] - nbt
        cl = lambda x, e: float(np.mean(np.asarray(M.clear(th, x, Lv, cv, eps=e)) / 10)); p0, p1, p2, p3, p4 = cl(xh, uh + nbh), cl(x1, uh + nbh), cl(x2, uh + nbh), cl(x2, uh + nbt), cl(x2, ut + nbt); act = a[j].mean()
        hn = pd.date_range(t0, periods=6, freq="1h"); hp = hn - pd.Timedelta(hours=24); dc = {k: float(R[k].reindex(hn).mean() - R[k].reindex(hp).mean()) for k in COMP}; loc = t0.tz_convert("Europe/Berlin")
        prev = float(np.mean(Z["p"][d0 - 96:d0 - 72])) / 10; xprev = float((Z["rl"][d0 - 96:d0 - 72] - Z["other"][d0 - 96:d0 - 72]).mean()); rows.append(dict(bw=float(BW[j]), blo=float(BLO[j]), bhi=float(BHI[j]), dx_fc=float(xh.mean()) - xprev, dx_true=float(x2.mean()) - xprev, per=per, date=str(loc.date()), wd=loc.day_name()[:3], act=act, prev=prev, err=p0 - act, err_ts=float(tp[j].mean()) - act, load=p0 - p1, other=p1 - p2, nb=p2 - p3, shift=p3 - p4, rest=p4 - act, dload=float((G["rl_pes"][j].astype(float)[:24] - rlt).mean()), dwind=float((G["wind_pes"][j].astype(float)[:24] - G["wind_true"][j].astype(float)[:24]).mean()), du=float((uh - ut).mean()), dL=Lj - float(Lact.reindex(hn).mean()), u_prev_change=float(ut.mean() - (Z["rl"][d0 - 96:d0 - 72] - Z["other"][d0 - 96:d0 - 72] - Z["Sp"][d0 - 96:d0 - 72] - Z["nbterm"][d0 - 96:d0 - 72]).mean()), **dc))
D = pd.DataFrame(rows); D.to_csv(f"{SP}/out/miss_look.csv", index=False); pd.set_option("display.width", 250); pd.set_option("display.max_columns", 40); f2 = lambda x: f"{x:+.2f}"
big = D[D.err.abs() > 1.5]; print("nights with night-level error above 1.5 ct:", len(big), "of", len(D), "by period", big.per.value_counts().to_dict(), "| they carry", round(float(big.err.abs().sum() / D.err.abs().sum()), 2), "of all night-level error")
for nm, S_ in (("all nights", D), ("misses > 1.5 ct", big), ("the rest", D[D.err.abs() <= 1.5])):
    sg = np.sign(S_.err); print(f"{nm}: mean |error| {S_.err.abs().mean():.2f} ct; signed share of the error from load forecast {(sg * S_.load).sum() / S_.err.abs().sum():.2f}, other plant {(sg * S_.other).sum() / S_.err.abs().sum():.2f}, neighbours {(sg * S_.nb).sum() / S_.err.abs().sum():.2f}, supply shift {(sg * S_['shift']).sum() / S_.err.abs().sum():.2f}, rest (fuel cost, convention) {(sg * S_.rest).sum() / S_.err.abs().sum():.2f}")
print(big.sort_values("err", key=np.abs, ascending=False)[["per", "date", "wd", "prev", "act", "err", "err_ts", "load", "other", "nb", "shift", "rest", "dload", "dwind", "du", "u_prev_change", "dL"] + COMP].to_string(index=False, float_format=lambda x: f"{x:+.1f}"))
ok = D[COMP + ["u_prev_change"]].dropna(); A = np.column_stack([ok[COMP].values, np.ones(len(ok))]); b = np.linalg.lstsq(A, ok.u_prev_change.values, rcond=None)[0]; print("night-to-night change of the shift on the changes of the six shocks, coefficients:", dict(zip(COMP, np.round(b[:6], 2))), "R2", round(1 - np.var(ok.u_prev_change.values - A @ b) / np.var(ok.u_prev_change.values), 2))
print("corr of shift surprise (forecast minus true, GW) with the night-to-night change of the true shift:", round(float(D.du.corr(D.u_prev_change)), 2), "| share of true change that the forecast captured (1 + slope):", round(1 + float(np.polyfit(D.u_prev_change, D.du, 1)[0]), 2))
print("misses: sign", (big.err > 0).sum(), "too high,", (big.err < 0).sum(), "too low | weekday counts", big.wd.value_counts().to_dict(), "| all nights weekday mean |err|", D.groupby("wd").err.apply(lambda x: round(x.abs().mean(), 2)).to_dict())
